}

public class Main {
    static long faktorial(int n) { return n <= 1 ? 1 : n * faktorial(n - 1); }
    static int luas(int s) { return s * s; }
    static int luas(int p, int l) { return p * l; }

    public static void main(String[] args) {
        System.out.println(faktorial(10) + " " + luas(3) + " " + luas(2, 5));
    }
}

